package android.content;import android.net.Uri;public class ClipData{final ClipDescription d;final java.util.List<Item> items=new java.util.ArrayList<>();public ClipData(ClipDescription x,Item i){d=x;items.add(i);}public ClipDescription getDescription(){return d;}public int getItemCount(){return items.size();}public Item getItemAt(int i){return items.get(i);}public void addItem(Item i){items.add(i);}public static class Item{final CharSequence text;final Uri uri;public Item(CharSequence t){text=t;uri=null;}public Item(Uri u){text=null;uri=u;}public CharSequence getText(){return text;}public Uri getUri(){return uri;}}}